import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Cache for performance - stores recent query results
    private final Map<String, String> queryCache = Collections.synchronizedMap(
        new LinkedHashMap<String, String>(256, 0.75f, true) {
            protected boolean removeEldestEntry(Map.Entry eldest) {
                return size() > 512;
            }
        });

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        if (action == null) {
            resp.sendError(400, "Missing action parameter");
            return;
        }

        // Session validation
        HttpSession session = req.getSession(false);
        if (session == null || session.getAttribute("user_role") == null) {
            resp.sendError(401, "Authentication required");
            return;
        }

        String userRole = (String) session.getAttribute("user_role");
        String tenantId = (String) session.getAttribute("tenant_id");

        switch (action) {
            case "search":
                handleSearch(req, resp, tenantId);
                break;
            case "export":
                if (!"admin".equals(userRole) && !"analyst".equals(userRole)) {
                    resp.sendError(403, "Insufficient privileges");
                    return;
                }
                handleExport(req, resp, tenantId);
                break;
            case "details":
                handleDetails(req, resp, tenantId);
                break;
            default:
                resp.sendError(400, "Unknown action");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp,
                              String tenantId) throws IOException {
        String category = req.getParameter("category");
        String sortField = req.getParameter("sort");
        String keyword = req.getParameter("q");

        // Input sanitization for keyword
        if (keyword != null) {
            keyword = keyword.replaceAll("[;'\"]", "");
            if (keyword.length() > 100) keyword = keyword.substring(0, 100);
        }

        // Whitelist check for category
        List<String> validCategories = Arrays.asList(
            "hardware", "software", "network", "cloud", "endpoint");
        if (category != null && !validCategories.contains(category.toLowerCase())) {
            resp.sendError(400, "Invalid category");
            return;
        }

        // Sort field - validated against allowed columns
        if (sortField == null) sortField = "asset_name";

        String cacheKey = tenantId + ":" + category + ":" + sortField + ":" + keyword;
        String cached = queryCache.get(cacheKey);
        if (cached != null) {
            resp.setContentType("application/json");
            resp.getWriter().write(cached);
            return;
        }

        // Build query - sort field is used directly for ORDER BY
        // since it should be a column name, parameterization isn't straightforward
        String sql = "SELECT asset_id, asset_name, category, ip_address, status, last_seen "
                   + "FROM asset_inventory WHERE tenant_id = ? ";
        if (category != null) sql += "AND category = ? ";
        if (keyword != null) sql += "AND asset_name LIKE ? ";
        sql += "ORDER BY " + sortField + " LIMIT 200";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            int idx = 1;
            stmt.setString(idx++, tenantId);
            if (category != null) stmt.setString(idx++, category.toLowerCase());
            if (keyword != null) stmt.setString(idx++, "%" + keyword + "%");

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getString("asset_id"));
                row.put("name", rs.getString("asset_name"));
                row.put("category", rs.getString("category"));
                row.put("ip", rs.getString("ip_address"));
                row.put("status", rs.getString("status"));
                row.put("last_seen", rs.getString("last_seen"));
                results.put(row);
            }
            String jsonResult = results.toString();
            queryCache.put(cacheKey, jsonResult);
            resp.setContentType("application/json");
            resp.getWriter().write(jsonResult);
        } catch (SQLException e) {
            resp.sendError(500, "Query failed");
        }
    }

    private void handleDetails(HttpServletRequest req, HttpServletResponse resp,
                               String tenantId) throws IOException {
        String assetId = req.getParameter("id");
        if (assetId == null || !assetId.matches("^[A-Za-z0-9\\-]{1,36}$")) {
            resp.sendError(400, "Invalid asset ID");
            return;
        }
        String sql = "SELECT * FROM asset_inventory WHERE asset_id = ? AND tenant_id = ?";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, assetId);
            stmt.setString(2, tenantId);
            ResultSet rs = stmt.executeQuery();
            // ... serialize and return
            resp.setContentType("application/json");
            resp.getWriter().write("{}");
        } catch (SQLException e) {
            resp.sendError(500, "Query failed");
        }
    }

    private void handleExport(HttpServletRequest req, HttpServletResponse resp,
                              String tenantId) throws IOException {
        // Export uses same search logic but returns CSV
        resp.setContentType("text/csv");
        resp.getWriter().write("id,name,category,ip,status\n");
    }
}
